\section*{خلاصہ}
یہ اقتباس ایک آبی جیل میٹرکس میں ڈفیوژن کوایفیشینٹس کی لیبارٹری پیمائش پر مبنی ہے۔ اس کا مقصد ایک لیب رپورٹ کے لیے مخصوص ڈیریویشنز اور ایرر انیلیسز کو ظاہر کرنا ہے جس میں LaTeX ریاضی، ایک مختصر تھیورم سٹیٹمنٹ، اور نمبر والے ڈیریویشنز شامل ہیں۔ کنسنٹریشن فیلڈ کو $c(x,t)$ اور ڈفیوزیوٹی کو $D$ سے ظاہر کیا گیا ہے۔ پیمائشیں تین درجہ حرارت پر کی گئیں۔

\section{تعارف}
پورس میڈیا میں ڈفیوژن کو اکثر ڈفیوژن مساوات کے ذریعے ماڈل کیا جاتا ہے۔ ایک یک جہتی، ہوموجینیس میڈیم کے لیے ہم لکھتے ہیں
\begin{equation}
\frac{\partial c}{\partial t} = D \frac{\partial^2 c}{\partial x^2},
\label{eq:diffusion}
\end{equation}
جہاں $c$ کی اکائیاں mol m$^{-3}$ اور $D$ کی اکائیاں m$^2$ s$^{-1}$ ہیں۔ $D$ کا درجہ حرارت پر انحصار اکثر ایک Arrhenius ریلیشن سے تخمینہ لگایا جاتا ہے،
$D = D_0 \exp\left(-\frac{E_a}{k_B T}\right)$،
جس میں ایکٹیویشن انرجی $E_a$ اور Boltzmann کانسٹنٹ $k_B$ شامل ہیں۔

\begin{theorem}[Fick کا پہلا قانون]
ایک سلیب میں سٹیڈی اسٹیٹ ڈفیوژن کے لیے، فلکس $J$ کنسنٹریشن گریڈینٹ کے متناسب ہوتا ہے:
\begin{equation}
J = -D \frac{\partial c}{\partial x}.
\end{equation}
\end{theorem}

\section{طریقہ کار}
جیل کے نمونے (موٹائی $L=5\ \text{mm}$) تیار کیے گئے اور $x=0$ پر ایک ٹریسر لگایا گیا۔ کنسنٹریشن پروفائلز $c(x,t)$ کو الگ الگ اوقات میں آپٹیکل ایبزاربنس کے ذریعے ماپا گیا۔ انجیکٹڈ والیوم کے لیے تجرباتی $\Delta V$ کی مقدار $0.50\ \text{mL}$ تھی جس میں $\pm 0.02\ \text{mL}$ کی غیر یقینی صورتحال تھی۔ کیلیبریشن ایبزاربنس سے کنسنٹریشن کو $c = \alpha A$ کے ذریعے فراہم کرتا ہے، جہاں $\alpha$ کو معیارات سے طے کیا جاتا ہے۔
